const { useEffect, useRef, useState } = React;

const KIT_STYLE = `
  @scope {
    .cb-grid {
      background-image: radial-gradient(var(--tau-line-1) 1px, transparent 1px);
      background-size: 16px 16px;
    }
    .cb-range { accent-color: var(--tau-accent); }
  }
`;

// 实验台骨架：左侧舞台放被演示元素，右侧面板放参数，底部是实时生成的声明
const Lab = ({ stage, children, code }) => (
  <div className="@container flex flex-col gap-3">
    <style>{KIT_STYLE}</style>
    <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
      <div className="cb-grid relative flex min-w-0 items-center justify-center rounded-tau-md border border-line-1 p-4">
        {stage}
      </div>
      <div className="flex min-w-0 flex-col gap-3 rounded-tau-md border border-line-1 p-3">{children}</div>
    </div>
    {code}
  </div>
);

const Options = ({ label, options, value, onChange }) => (
  <div className="flex min-w-0 flex-col gap-1.5">
    <span className="text-tau-sm text-ink-3">{label}</span>
    <div className="flex flex-wrap gap-1.5">
      {options.map(option => {
        const item = typeof option === "string" ? { value: option, label: option } : option;
        const active = item.value === value;
        return (
          <button
            key={item.value}
            type="button"
            aria-pressed={active}
            onClick={() => onChange(item.value)}
            className={`max-w-full cursor-pointer rounded-tau-sm border px-2 py-0.5 text-left font-tau-mono text-tau-sm transition-colors ${
              active ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
            }`}
          >
            {item.label}
          </button>
        );
      })}
    </div>
  </div>
);

const Slider = ({ label, value, min, max, step = 1, onChange, format = value => value }) => (
  <label className="flex min-w-0 flex-col gap-1">
    <span className="flex items-baseline justify-between gap-2 text-tau-sm text-ink-3">
      <span>{label}</span>
      <span className="font-tau-mono text-ink-1">{format(value)}</span>
    </span>
    <input
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      onChange={event => onChange(Number(event.target.value))}
      className="cb-range h-1.5 w-full cursor-pointer"
    />
  </label>
);

const Readout = ({ rows }) => (
  <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-3 gap-y-1 border-t border-line-2 pt-2.5 text-tau-sm">
    {rows.map(([label, value]) => (
      <React.Fragment key={label}>
        <dt className="text-ink-3">{label}</dt>
        <dd className="m-0 min-w-0 break-all text-right font-tau-mono text-ink-1">{value}</dd>
      </React.Fragment>
    ))}
  </dl>
);

// 声明读数：每行由字符串和 { mark } 段组成，mark 段是当前正在调的参数
const Code = ({ lines }) => (
  <code className="block min-w-0 break-all rounded-tau-md bg-hover px-3 py-2 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
    {lines.map((line, lineIndex) => (
      <div key={lineIndex}>
        {line.map((part, index) =>
          typeof part === "string" ? (
            <span key={index}>{part}</span>
          ) : (
            <span key={index} className="rounded-tau-sm bg-accent-soft px-0.5 text-accent-text">
              {part.mark}
            </span>
          )
        )}
      </div>
    ))}
  </code>
);

// 跟随元素尺寸（渐变盒子的宽高决定结束形状、渐变线长度）
const useSize = () => {
  const ref = useRef(null);
  const [size, setSize] = useState({ width: 0, height: 0 });
  useEffect(() => {
    const element = ref.current;
    if (!element) return;
    const measure = () => setSize({ width: element.clientWidth, height: element.clientHeight });
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  return [ref, size];
};

const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
// 在元素上按下并拖动：回调盒内坐标（CSS 像素）与盒子尺寸
const dragProps = (ref, onMove) => {
  const move = event => {
    const rect = ref.current?.getBoundingClientRect();
    if (!rect?.width || !rect.height) return;
    onMove(clamp(event.clientX - rect.left, 0, rect.width), clamp(event.clientY - rect.top, 0, rect.height), rect);
  };
  return {
    onPointerDown: event => {
      event.currentTarget.setPointerCapture?.(event.pointerId);
      move(event);
    },
    onPointerMove: event => {
      if (event.buttons & 1) move(event);
    },
  };
};

// 辅助线：底下垫一层 surface 色描边，在任何渐变色上都清晰
const Guide = ({ dashed = true, ...props }) => (
  <>
    <line {...props} className="stroke-surface" strokeWidth="3" strokeLinecap="round" />
    <line {...props} className="stroke-ink-1" strokeWidth="1.25" strokeDasharray={dashed ? "4 3" : undefined} />
  </>
);
const Dot = ({ x, y }) => <circle cx={x} cy={y} r="4.5" className="fill-surface stroke-ink-1" strokeWidth="1.5" />;
const Label = ({ x, y, children, anchor = "middle" }) => (
  <text
    x={x}
    y={y}
    textAnchor={anchor}
    dominantBaseline="middle"
    className="fill-ink-1 stroke-surface font-tau-mono text-tau-tiny"
    strokeWidth="3"
    style={{ paintOrder: "stroke" }}
  >
    {children}
  </text>
);
const Overlay = ({ width, height, children }) =>
  width > 0 && height > 0 ? (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      className="pointer-events-none absolute inset-0 size-full overflow-hidden rounded-tau-sm"
    >
      {children}
    </svg>
  ) : null;

const STOPS = "#FFF6B7 10%, #F6416C 100%";
const MODES = [{ value: "angle", label: "<angle>" }, { value: "keyword", label: "to <side-or-corner>" }];
// 罗盘排布的八个方向关键字，中间格留空
const COMPASS = [
  ["to left top", -45], ["to top", 0], ["to right top", 45],
  ["to left", -90], null, ["to right", 90],
  ["to left bottom", -135], ["to bottom", 180], ["to right bottom", 135],
];
const DIAL = 96;
const toDeg = radian => (radian * 180) / Math.PI;

// 角关键字的实际角度取决于盒子宽高比：渐变线垂直于另外两个角的连线
const keywordAngle = (keyword, width, height) => {
  const corner = width > 0 ? toDeg(Math.atan2(height, width)) : 45;
  const table = {
    "to top": 0, "to right": 90, "to bottom": 180, "to left": 270,
    "to right top": corner, "to right bottom": 180 - corner, "to left bottom": 180 + corner, "to left top": 360 - corner,
  };
  return table[keyword];
};

const Component = () => {
  const dialRef = useRef(null);
  const [mode, setMode] = useState("angle");
  const [angle, setAngle] = useState(45);
  const [keyword, setKeyword] = useState("to right top");
  const [boxWidth, setBoxWidth] = useState(100);
  const [boxRef, { width, height }] = useSize();
  const direction = mode === "angle" ? `${angle}deg` : keyword;
  const effective = mode === "angle" ? angle : keywordAngle(keyword, width, height);
  const theta = (effective * Math.PI) / 180;
  const sin = Math.sin(theta);
  const cos = Math.cos(theta);
  const length = Math.abs(width * sin) + Math.abs(height * cos);
  const cx = width / 2;
  const cy = height / 2;
  const start = { x: cx - (length / 2) * sin, y: cy + (length / 2) * cos };
  const end = { x: cx + (length / 2) * sin, y: cy - (length / 2) * cos };
  const reach = width + height;
  const drag = dragProps(dialRef, (x, y) => {
    setMode("angle");
    setAngle((Math.round(toDeg(Math.atan2(x - DIAL / 2, DIAL / 2 - y))) + 360) % 360);
  });
  const knob = { x: DIAL / 2 + 36 * Math.sin(theta), y: DIAL / 2 - 36 * Math.cos(theta) };

  return (
    <Lab
      stage={
        <div
          ref={boxRef}
          className="relative h-[180px] rounded-tau-sm shadow-card transition-[width] duration-300 ease-tau-out"
          style={{ width: `${boxWidth}%`, backgroundImage: `linear-gradient(${direction}, ${STOPS})` }}
        >
          <Overlay width={width} height={height}>
            {[start, end].map((point, index) => (
              <Guide key={index} x1={point.x - cos * reach} y1={point.y - sin * reach} x2={point.x + cos * reach} y2={point.y + sin * reach} />
            ))}
            <Guide x1={start.x} y1={start.y} x2={end.x} y2={end.y} dashed={false} />
            <Dot x={start.x} y={start.y} />
            <Dot x={end.x} y={end.y} />
            <Label x={cx + 14 * cos} y={cy + 14 * sin}>渐变线</Label>
          </Overlay>
        </div>
      }
      code={<Code lines={[["background-image: linear-gradient(", { mark: direction }, `, ${STOPS});`]]} />}
    >
      <Options label="方向写法" options={MODES} value={mode} onChange={setMode} />
      <div className="flex flex-wrap items-center gap-4">
        <div ref={dialRef} {...drag} className="relative shrink-0 cursor-pointer touch-none" style={{ width: DIAL, height: DIAL }}>
          <svg viewBox={`0 0 ${DIAL} ${DIAL}`} className="pointer-events-none size-full">
            <circle cx={DIAL / 2} cy={DIAL / 2} r="36" fill="none" className="stroke-line-1" strokeWidth="6" />
            <line x1={DIAL / 2} y1={DIAL / 2} x2={knob.x} y2={knob.y} className="stroke-accent" strokeWidth="2" />
            <circle cx={knob.x} cy={knob.y} r="7" className="fill-accent stroke-surface" strokeWidth="2" />
            <text x={DIAL / 2} y="6" textAnchor="middle" dominantBaseline="middle" className="fill-ink-3 font-tau-mono text-tau-tiny">0</text>
          </svg>
        </div>
        <div className="grid grid-cols-3 gap-1">
          {COMPASS.map((item, index) =>
            item ? (
              <ui.Tooltip key={item[0]} content={item[0]}>
                <button
                  type="button"
                  aria-label={item[0]}
                  aria-pressed={mode === "keyword" && keyword === item[0]}
                  onClick={() => {
                    setMode("keyword");
                    setKeyword(item[0]);
                  }}
                  className={`grid size-8 cursor-pointer place-items-center rounded-tau-sm border transition-colors ${
                    mode === "keyword" && keyword === item[0]
                      ? "border-accent bg-accent-soft text-accent-text"
                      : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
                  }`}
                >
                  <icons.ArrowUp className="size-4" style={{ transform: `rotate(${item[1]}deg)` }} />
                </button>
              </ui.Tooltip>
            ) : (
              <span key={index} />
            )
          )}
        </div>
      </div>
      <Slider label="盒子宽度" value={boxWidth} min={40} max={100} onChange={setBoxWidth} format={value => `${value}%`} />
      <Readout
        rows={[
          ["写法", direction],
          ["等效角度", `${Number(effective.toFixed(1))}deg`],
          ["渐变线长度", `${Math.round(length)}px`],
        ]}
      />
    </Lab>
  );
};

