      className="cb-range h-1.5 w-full cursor-pointer"
    />
  </label>
);

const Readout = ({ rows }) => (
  <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-3 gap-y-1 border-t border-line-2 pt-2.5 text-tau-sm">
    {rows.map(([label, value]) => (
      <React.Fragment key={label}>
        <dt className="text-ink-3">{label}</dt>
        <dd className="m-0 min-w-0 break-all text-right font-tau-mono text-ink-1">{value}</dd>
      </React.Fragment>
    ))}
  </dl>
);

// 声明读数：每行由字符串和 { mark } 段组成，mark 段是当前正在调的参数
const Code = ({ lines }) => (
  <code className="block min-w-0 break-all rounded-tau-md bg-hover px-3 py-2 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
    {lines.map((line, lineIndex) => (
      <div key={lineIndex}>
        {line.map((part, index) =>
          typeof part === "string" ? (
            <span key={index}>{part}</span>
          ) : (
            <span key={index} className="rounded-tau-sm bg-accent-soft px-0.5 text-accent-text">
              {part.mark}
            </span>
          )
        )}
      </div>
    ))}
  </code>
);

const PALETTE = ["red", "orange", "yellow", "green", "blue", "purple", "#FCCF31", "#FFCC55", "#F55555", "#12c2e9", "#c471ed", "#f64f59"];
const stop = (color, position = null) => ({ color, position });
const PRESETS = [
  ["red", "orange", "yellow", "green", "blue", "purple"].map(color => stop(color)),
  [stop("#FCCF31", 0), stop("#FFCC55"), stop("#F55555", 100)],
  [stop("#12c2e9"), stop("#c471ed", 30), stop("#f64f59")],
  [stop("red", 25), stop("blue", 75)],
];
const stopText = ({ color, position }) => (position === null ? color : `${color} ${position}%`);
const listText = stops => stops.map(stopText).join(", ");
const POSITION_MODES = [{ value: "auto", label: "省略" }, { value: "explicit", label: "指定" }];

// 规范的补全规则：首尾缺省取 0% / 100%，小于前一个的取前一个，中间缺省的均分
const resolve = stops => {
  const positions = stops.map(item => item.position);
  if (positions[0] === null) positions[0] = 0;
  if (positions.at(-1) === null) positions[positions.length - 1] = 100;
  let max = 0;
  positions.forEach((value, index) => {
    if (value === null) return;
    max = Math.max(max, value);
    positions[index] = max;
  });
  for (let index = 1; index < positions.length; index++) {
    if (positions[index] !== null) continue;
    const before = index - 1;
    let after = index;
    while (positions[after] === null) after++;
    const step = (positions[after] - positions[before]) / (after - before);
    for (let fill = index; fill < after; fill++) positions[fill] = positions[before] + step * (fill - before);
  }
  return positions.map(value => Number(value.toFixed(1)));
};

const Component = () => {
  const [stops, setStops] = useState(PRESETS[0]);
  const [selected, setSelected] = useState(0);
  const resolved = resolve(stops);
  const current = stops[selected] ?? stops[0];
  const update = patch => setStops(list => list.map((item, index) => (index === selected ? { ...item, ...patch } : item)));
  const choosePreset = text => {
    setStops(PRESETS.find(preset => listText(preset) === text));
    setSelected(0);
  };
  const add = () => {
    const color = PALETTE[(PALETTE.indexOf(current.color) + 1) % PALETTE.length];
    setStops(list => [...list.slice(0, selected + 1), stop(color), ...list.slice(selected + 1)]);
    setSelected(selected + 1);
  };
  const remove = () => {
    setStops(list => list.filter((_, index) => index !== selected));
    setSelected(Math.max(0, selected - 1));
  };
  const first = resolved[0];
  const last = resolved.at(-1);

  return (
    <Lab
      stage={
        <div className="flex w-full flex-col gap-2">
          <div className="h-16 rounded-tau-sm shadow-card" style={{ backgroundImage: `linear-gradient(to right, ${listText(stops)})` }} />
          <div className="relative mx-2 h-6">
            {resolved.map((value, index) => (
              <button
                key={index}
                type="button"
                aria-label={`第 ${index + 1} 个色标`}
                onClick={() => setSelected(index)}
                className={`absolute top-1 size-4 -translate-x-1/2 cursor-pointer rounded-full border-2 transition-[left] duration-300 ease-tau-out ${
                  stops[index].position === null ? "border-dashed border-ink-3" : "border-surface shadow-card"
                } ${index === selected ? "ring-2 ring-accent" : ""}`}
                style={{ left: `${value}%`, backgroundColor: stops[index].color }}
              />
            ))}
          </div>
          <div className="mx-2 flex justify-between font-tau-mono text-tau-tiny text-ink-3">
            <span>0%</span>
            <span>50%</span>
            <span>100%</span>
          </div>
          <span className="text-tau-meta text-ink-3">实心圆点为写明的位置，虚线圆点为补全出来的位置，点击圆点可编辑。</span>
        </div>
      }
      code={
        <Code
          lines={[
            [
              "background-image: linear-gradient(to right, ",
              ...stops.flatMap((item, index) => [index ? ", " : "", index === selected ? { mark: stopText(item) } : stopText(item)]),
              ");",
            ],
          ]}
        />
      }
    >
      <Options label="示例" options={PRESETS.map(listText)} value={listText(stops)} onChange={choosePreset} />
      <div className="flex flex-col gap-2 border-t border-line-2 pt-2.5">
        <div className="flex items-center justify-between gap-2">
          <span className="text-tau-sm text-ink-2">第 {selected + 1} 个色标</span>
          <div className="flex gap-1">
            <ui.Button variant="ghost" size="sm" icon={icons.Plus} onClick={add}>
              添加色标
            </ui.Button>
            <ui.IconButton aria-label="删除色标" disabled={stops.length <= 2} onClick={remove}>
              <icons.Trash2 className="size-4" />
            </ui.IconButton>
          </div>
        </div>
        <div className="flex flex-wrap gap-1.5">
          {PALETTE.map(color => (
            <ui.Tooltip key={color} content={color}>
              <button
                type="button"
                aria-label={color}
                onClick={() => update({ color })}
                className={`size-5 cursor-pointer rounded-full border border-line-1 ${current.color === color ? "ring-2 ring-accent" : ""}`}
                style={{ backgroundColor: color }}
              />
            </ui.Tooltip>
          ))}
        </div>
        <Options
          label="位置"
          options={POSITION_MODES}
          value={current.position === null ? "auto" : "explicit"}
          onChange={value => update({ position: value === "auto" ? null : Math.round(resolved[selected]) })}
        />
        {current.position !== null && (
          <Slider label="position" value={current.position} min={0} max={100} onChange={position => update({ position })} format={value => `${value}%`} />
        )}
      </div>
      <Readout
        rows={[
          ["解析后", stops.map((item, index) => `${item.color} ${resolved[index]}%`).join(", ")],
          ...(first > 0 ? [["起点段", `0% – ${first}%：纯色 ${stops[0].color}`]] : []),
          ...(last < 100 ? [["终点段", `${last}% – 100%：纯色 ${stops.at(-1).color}`]] : []),
        ]}
      />
    </Lab>
  );
};

