);

const Slider = ({ label, value, min, max, step = 1, onChange, format = value => value }) => (
  <label className="flex min-w-0 flex-col gap-1">
    <span className="flex items-baseline justify-between gap-2 text-tau-sm text-ink-3">
      <span>{label}</span>
      <span className="font-tau-mono text-ink-1">{format(value)}</span>
    </span>
    <input
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      onChange={event => onChange(Number(event.target.value))}
      className="cb-range h-1.5 w-full cursor-pointer"
    />
  </label>
);

const Readout = ({ rows }) => (
  <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-3 gap-y-1 border-t border-line-2 pt-2.5 text-tau-sm">
    {rows.map(([label, value]) => (
      <React.Fragment key={label}>
        <dt className="text-ink-3">{label}</dt>
        <dd className="m-0 min-w-0 break-all text-right font-tau-mono text-ink-1">{value}</dd>
      </React.Fragment>
    ))}
  </dl>
);

// 声明读数：每行由字符串和 { mark } 段组成，mark 段是当前正在调的参数
const Code = ({ lines }) => (
  <code className="block min-w-0 break-all rounded-tau-md bg-hover px-3 py-2 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
    {lines.map((line, lineIndex) => (
      <div key={lineIndex}>
        {line.map((part, index) =>
          typeof part === "string" ? (
            <span key={index}>{part}</span>
          ) : (
            <span key={index} className="rounded-tau-sm bg-accent-soft px-0.5 text-accent-text">
              {part.mark}
            </span>
          )
        )}
      </div>
    ))}
  </code>
);

const FROM = "#97ABFF";
const TO = "#123597";
const MODES = [{ value: "hint", label: "带 color-hint" }, { value: "none", label: "不带" }];
const CHART = { width: 240, height: 110 };

// color-hint 位于 H 时，两色之间位置 t 处第二个颜色的占比为 t^(ln0.5 / lnH)，中点恰好落在 H
const exponentOf = hint => Math.log(0.5) / Math.log(hint / 100);

const Component = () => {
  const [mode, setMode] = useState("hint");
  const [hint, setHint] = useState(20);
  const midpoint = mode === "hint" ? hint : 50;
  const exponent = exponentOf(midpoint);
  const gradient = mode === "hint" ? `linear-gradient(to right, ${FROM}, ${hint}%, ${TO})` : `linear-gradient(to right, ${FROM}, ${TO})`;
  const points = Array.from({ length: 61 }, (_, index) => {
    const t = index / 60;
    return `${t * CHART.width},${CHART.height - t ** exponent * CHART.height}`;
  }).join(" ");

  return (
    <Lab
      stage={
        <div className="flex w-full flex-col gap-2">
          <div className="relative h-14 rounded-tau-sm shadow-card" style={{ backgroundImage: gradient }}>
            <span
              className="absolute inset-y-0 w-0 border-l-2 border-dashed border-surface transition-[left] duration-200 ease-tau-out"
              style={{ left: `${midpoint}%` }}
            />
          </div>
          <div className="relative h-[110px]">
            <svg viewBox={`0 0 ${CHART.width} ${CHART.height}`} preserveAspectRatio="none" className="size-full overflow-visible">
              <rect x="0" y="0" width={CHART.width} height={CHART.height} fill="none" className="stroke-line-1" vectorEffect="non-scaling-stroke" />
              <line x1="0" y1={CHART.height} x2={CHART.width} y2="0" className="stroke-line-1" strokeDasharray="3 3" vectorEffect="non-scaling-stroke" />
              <line x1="0" y1={CHART.height / 2} x2={CHART.width} y2={CHART.height / 2} className="stroke-line-2" strokeDasharray="2 3" vectorEffect="non-scaling-stroke" />
              <polyline points={points} fill="none" className="stroke-accent" strokeWidth="2" vectorEffect="non-scaling-stroke" />
            </svg>
            <span
              className="absolute size-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-surface bg-accent"
              style={{ left: `${midpoint}%`, top: "50%" }}
            />
          </div>
          <div className="flex justify-between font-tau-mono text-tau-tiny text-ink-3">
            <span>{FROM}</span>
            <span>横轴位置，纵轴 {TO} 的占比</span>
            <span>{TO}</span>
          </div>
        </div>
      }
      code={
        <Code
          lines={[
            mode === "hint"
              ? ["background-image: linear-gradient(to right, ", FROM, ", ", { mark: `${hint}%` }, `, ${TO});`]
              : [`background-image: linear-gradient(to right, ${FROM}, ${TO});`],
          ]}
        />
      }
    >
      <Options label="<linear-color-hint>" options={MODES} value={mode} onChange={setMode} />
      {mode === "hint" && <Slider label="颜色中点" value={hint} min={5} max={95} onChange={setHint} format={value => `${value}%`} />}
      <Readout
        rows={[
          ["两色各半处", `${midpoint}%`],
          ["插值曲线", midpoint === 50 ? "直线" : `t^${exponent.toFixed(2)}`],
        ]}
      />
      <span className="text-tau-meta text-ink-3">虚线对角线是不带 hint 时的匀速过渡，圆点处两种颜色各占一半。</span>
    </Lab>
  );
};
